        const trip={id:working.id,name:working.name,originZone:flights[0].departureZone,originLocation:flights[0].departureLocation||'',originZoneLocation:flights[0].departureZoneLocation||null,origin:copy(flights[0].from)||null,flights};T.validate(trip);
        const trips=copy(p.trips||[]),at=trips.findIndex(t=>t.id===editing);if(at>=0)trips.splice(at,1,trip);else trips.push(trip);const changes={trips};if(p.trips?.find(t=>t.id===editing)?.legacy)changes.flights=(p.flights||[]).filter((f,i)=>!p.trips.find(t=>t.id===editing).flights.some(leg=>leg.id===(f.id||'legacy-flight:'+i)));await env.patch(p.id,changes,expected);if(submissionSerial===serial&&submissionWorking===working)finish();
