    function refreshNotices(){const c=context(),allowed=new Set(c.calendarIds||[]),loaded=[...records.values()].filter(r=>allowed.has(r.cal?.id));for(const p of c.state.profiles)for(const trip of p.trips||[])for(const f of trip.flights||[])if(f.link&&!allowed.has(f.link.calendarId)&&!loaded.some(r=>r.cal?.id===f.link.calendarId))loaded.push({cal:{id:f.link.calendarId,summary:f.link.calendarName||'Calendar'},source:{items:[],coverage:{complete:false},failure:'Calendar not selected or accessible'}});notices=c.account?c.state.profiles.flatMap(p=>T.observe(p,loaded,lookup).map(n=>({...n,profileName:p.name||p.email}))).filter(n=>!(c.state.profiles.find(p=>p.id===n.profileId)?.flightDismissals||[]).includes(n.id+'|'+n.status+'|'+(n.event?T.signature(n.event):''))):[];notices=[...new Map(notices.map(n=>[n.profileId+'|'+n.id,n])).values()];env.alertsChanged?.();}
    function alertHTML(){return notices.map((n,i)=>'<article class="meeting-entry trip-alert"><h3>'+esc(n.kind==='possible'?'Possible flight':n.status==='changed'?'Flight details changed':'Flight needs review')+'</h3><p><strong>'+esc(n.profileName)+'</strong> · '+esc(n.title)+'</p><p>'+esc(n.kind==='possible'?'Add this flight to a trip to use its times and destination.':n.status==='access'?'The linked calendar could not be checked. Your saved flight is unchanged.':n.status==='cancelled'?'The calendar event was cancelled. Your saved flight is unchanged.':n.status==='missing'?'The linked event was not found. Your saved flight is unchanged.':'Review the calendar’s updated details before changing the saved flight.')+'</p><div class="trip-entry-actions"><button type="button" data-trip-alert="'+i+'">'+(n.kind==='possible'?'Add flight':'Review flight')+'</button><button type="button" class="text-button" data-trip-dismiss="'+i+'">'+(n.kind==='possible'?'Dismiss':'Keep saved flight')+'</button></div></article>').join('');}
